class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int _pestanaActual = 0;
  bool _agenteActivo = false;
  final List<StreamSubscription<WatchEvent>> _watchersSubs = [];
  Timer? _pollingCarpetaTimer;
  Timer? _syncTimer;

  final List<EjercicioResuelto> _historial = [];
  final List<PptCompartido> _pptsDeLaSala = [];
  final Set<String> _idsEliminados = {};
  final Set<String> _archivosYaVistos = {};

  final String _rutaCarpeta = '/storage/emulated/0/Pictures/SayCheese';
  final List<String> _rutasVigiladas = [
    '/storage/emulated/0/Pictures/SayCheese',
    '/storage/emulated/0/DCIM/SayCheese',
    '/storage/emulated/0/SayCheese',
    '/storage/emulated/0/Download/SayCheese',
  ];

  final String _rutaRespaldoFijo =
      '/storage/emulated/0/Pictures/SayCheese/.saycheese_historial_v12.json';

  String _apiKey = const String.fromEnvironment(
    'GEMINI_API_KEY',
    defaultValue: '',
  );

  String _modeloSeleccionado = 'gemini-3.1-pro-preview';
  final List<String> _modelosDisponibles = [
    'gemini-3.1-pro-preview',
    'gemini-3-flash-preview',
    'gemini-2.5-pro',
    'gemini-2.5-flash',
    'gemini-2.0-flash',
  ];

  String _codigoSala = '';
  String _aliasUsuario = 'conrads';
  bool _sincronizando = false;
  String _estadoSala = 'Conectado';

  String _nombreArchivoContexto = '';
  String _autorPptActivo = '';
  String _textoExtraidoPpt = '';
  String? _base64PdfContexto;

  @override
  void initState() {
    super.initState();
    _inicializarTodo();
  }

  Future<void> _inicializarTodo() async {
    await _cargarDatosLocales();
    await _iniciarAgente();
    _syncTimer = Timer.periodic(const Duration(seconds: 5), (_) {
      if (_codigoSala.isNotEmpty) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  String _limpiarCodigoSala(String raw) {
    return raw
        .trim()
        .toUpperCase()
        .replaceAll(RegExp(r'\s+'), '')
        .replaceAll(RegExp(r'[^A-Z0-9-]'), '');
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      _apiKey = savedKey;
    }

    final savedModel = prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      if (!_modelosDisponibles.contains(savedModel)) {
        _modelosDisponibles.insert(0, savedModel);
      }
      _modeloSeleccionado = savedModel;
    }

    _codigoSala = _limpiarCodigoSala(prefs.getString('sala_compartida') ?? '');
    _aliasUsuario = prefs.getString('alias_usuario') ?? 'conrads';
    _nombreArchivoContexto = prefs.getString('ppt_nombre') ?? '';
    _autorPptActivo = prefs.getString('ppt_autor') ?? '';
    _textoExtraidoPpt = prefs.getString('ppt_texto') ?? '';
    _base64PdfContexto = prefs.getString('pdf_base64');

    final eliminadosGuardados = prefs.getStringList('ids_eliminados_v12') ??
        prefs.getStringList('ids_eliminados_v11') ??
        prefs.getStringList('ids_eliminados_v10') ??
        [];
    _idsEliminados
      ..clear()
      ..addAll(eliminadosGuardados);

    final vistosGuardados = prefs.getStringList('archivos_vistos_v12') ?? [];
    _archivosYaVistos
      ..clear()
      ..addAll(vistosGuardados);

    final pptsJson =
        prefs.getString('ppts_sala_v12') ?? prefs.getString('ppts_sala_v11');
    if (pptsJson != null && pptsJson.isNotEmpty) {
      try {
        final List rawPpts = jsonDecode(pptsJson);
        _pptsDeLaSala
          ..clear()
          ..addAll(rawPpts
              .map((e) => PptCompartido.fromJson(e as Map<String, dynamic>)));
      } catch (_) {}
    }

    List<EjercicioResuelto> cargados = [];

    try {
      final rawUnificado = prefs.getString('historial_json_completo_v12') ??
          prefs.getString('historial_json_completo_v11') ??
          prefs.getString('historial_json_completo_v10') ??
          prefs.getString('historial_json_completo_v7');
      if (rawUnificado != null && rawUnificado.isNotEmpty) {
        final List listaRaw = jsonDecode(rawUnificado);
        cargados = listaRaw
            .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
            .where((e) => !_idsEliminados.contains(e.id))
            .toList();
      }
    } catch (_) {}

    if (cargados.isEmpty) {
      try {
        final file = File(_rutaRespaldoFijo);
        if (await file.exists()) {
          final contenido = await file.readAsString();
          if (contenido.isNotEmpty) {
            final List listaRaw = jsonDecode(contenido);
            cargados = listaRaw
                .map((e) =>
                    EjercicioResuelto.fromJson(e as Map<String, dynamic>))
                .where((e) => !_idsEliminados.contains(e.id))
                .toList();
          }
        }
      } catch (_) {}
    }

    for (final c in cargados) {
      if (c.rutaImagen != null) {
        _archivosYaVistos.add(c.rutaImagen!);
      }
    }

    if (mounted) {
      setState(() {
        _historial
          ..clear()
          ..addAll(cargados);
      });
    }

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

  Future<void> _guardarHistorialLocal() async {
    final listaMap = _historial.map((e) => e.toJson()).toList();
    final jsonCompleto = jsonEncode(listaMap);
    final jsonPpts = jsonEncode(_pptsDeLaSala.map((p) => p.toJson()).toList());

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('historial_json_completo_v12', jsonCompleto);
      await prefs.setString('historial_json_completo_v11', jsonCompleto);
      await prefs.setString('ppts_sala_v12', jsonPpts);
      await prefs.setStringList('ids_eliminados_v12', _idsEliminados.toList());
      await prefs.setStringList(
          'archivos_vistos_v12', _archivosYaVistos.toList());
    } catch (_) {}

    try {
      final file = File(_rutaRespaldoFijo);
      await file.writeAsString(jsonCompleto, flush: true);
    } catch (_) {}
  }

  Future<void> _eliminarSolucion(EjercicioResuelto item) async {
    setState(() {
      _idsEliminados.add(item.id);
      _historial.removeWhere((e) => e.id == item.id);
    });
    await _guardarHistorialLocal();
    await _publicarEventoEnSala({
      'tipo': 'eliminar_solucion',
      'id': item.id,
      'emisor': _aliasUsuario,
    });
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Solucion eliminada.'),
          duration: Duration(seconds: 2),
        ),
      );
    }
  }

  Future<void> _confirmarBorrarTodasLasSoluciones() async {
    final confirmar = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Vaciar Solucionario'),
        content: const Text(
            '¿Seguro que quieres eliminar todas las soluciones guardadas?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Cancelar'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: Colors.redAccent),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Eliminar Todas'),
          ),
        ],
      ),
    );

    if (confirmar == true) {
      setState(() {
        for (final e in _historial) {
          _idsEliminados.add(e.id);
        }
        _historial.clear();
      });
      await _guardarHistorialLocal();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
              content: Text('Todas las soluciones fueron eliminadas.')),
        );
      }
    }
  }

  String _extraerTextoDeBytesPptx(List<int> bytes) {
    final archive = ZipDecoder().decodeBytes(bytes);
    final slidesBuffer = StringBuffer();
    int numSlide = 0;

    final slideFiles = archive.files
        .where((f) =>
            f.name.startsWith('ppt/slides/slide') && f.name.endsWith('.xml'))
        .toList();
    slideFiles.sort((a, b) => a.name.compareTo(b.name));

    final regExpTexto = RegExp(r'<a:t[^>]*>(.*?)</a:t>');

    for (final file in slideFiles) {
      numSlide++;
      final content =
          utf8.decode(file.content as List<int>, allowMalformed: true);
      final matches = regExpTexto.allMatches(content);
      final textoSlide = matches
          .map((m) => m.group(1) ?? '')
          .where((t) => t.trim().isNotEmpty)
          .join(' ');
      if (textoSlide.isNotEmpty) {
        slidesBuffer.writeln('--- Diapositiva $numSlide ---');
        slidesBuffer.writeln(textoSlide);
      }
    }
    return slidesBuffer.toString().trim();
  }

  Future<void> _activarYCompartirPpt({
    required String nombre,
    required String textoExtraido,
    required String autor,
    String? base64Pdf,
    bool compartirEnSala = true,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('ppt_nombre', nombre);
    await prefs.setString('ppt_autor', autor);
    await prefs.setString('ppt_texto', textoExtraido);
    if (base64Pdf != null) {
      await prefs.setString('pdf_base64', base64Pdf);
    } else {
      await prefs.remove('pdf_base64');
    }

    final nuevoPpt = PptCompartido(
      id: '${nombre}_$autor',
      nombre: nombre,
      autor: autor,
      textoExtraido: textoExtraido,
      fecha: DateTime.now(),
    );

    if (mounted) {
      setState(() {
        _nombreArchivoContexto = nombre;
        _autorPptActivo = autor;
        _textoExtraidoPpt = textoExtraido;
        _base64PdfContexto = base64Pdf;
        _pptsDeLaSala.removeWhere((p) => p.nombre == nombre);
        _pptsDeLaSala.insert(0, nuevoPpt);
      });
    }
    await _guardarHistorialLocal();

    if (compartirEnSala && _codigoSala.isNotEmpty && textoExtraido.isNotEmpty) {
      await _publicarPptEnSala(nuevoPpt);
    }
  }

  Future<void> _procesarBytesDeArchivoSubido(
      String nombre, List<int> bytes, String b64Data) async {
    final ext = nombre.toLowerCase();
    if (ext.endsWith('.pptx')) {
      final textoFinal = _extraerTextoDeBytesPptx(bytes);
      if (textoFinal.isEmpty) {
        throw Exception('No se encontro texto legible dentro del PPTX.');
      }
      await _activarYCompartirPpt(
        nombre: nombre,
        textoExtraido: textoFinal,
        autor: _aliasUsuario,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content:
                  Text('PPT cargado y compartido con tu sala: $nombre')),
        );
      }
    } else if (ext.endsWith('.pdf')) {
      await _activarYCompartirPpt(
        nombre: nombre,
        textoExtraido:
            '[Documento PDF cargado por $_aliasUsuario: $nombre]',
        autor: _aliasUsuario,
        base64Pdf: b64Data,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text('PDF cargado y compartido en la sala: $nombre')),
        );
      }
    } else {
      String texto = '';
      try {
        texto = _extraerTextoDeBytesPptx(bytes);
      } catch (_) {
        texto = utf8.decode(bytes, allowMalformed: true);
      }
      await _activarYCompartirPpt(
        nombre: nombre,
        textoExtraido: texto,
        autor: _aliasUsuario,
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content:
                  Text('Archivo cargado y compartido en la sala: $nombre')),
        );
      }
    }
  }

  // Selector de archivos 100% en Dart puro (no depende de plugins ni de MainActivity.kt, por lo que NUNCA da MissingPluginException ni falla al compilar)
  Future<void> _mostrarExploradorInternoDeArchivos(
      {required bool paraFoto}) async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    final archivos = paraFoto
        ? await _buscarFotosEnTelefono()
        : await _buscarArchivosPptEnTelefono();
    if (!mounted) return;
    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(paraFoto
            ? 'Elegir Foto de Hoja para Resolver'
            : 'Elegir PPT / PDF del Telefono'),
        content: SizedBox(
          width: double.maxFinite,
          height: 320,
          child: archivos.isEmpty
              ? Center(
                  child: Text(paraFoto
                      ? 'No se encontraron fotos en SayCheese, Camara o Descargas.'
                      : 'No se encontraron archivos .pptx o .pdf en Descargas o Documentos. Usa el cuadro de enlace de Google Drive / Slides arriba.'))
              : ListView.builder(
                  itemCount: archivos.length,
                  itemBuilder: (_, i) {
                    final f = archivos[i];
                    final name = f.path.split('/').last;
                    return Card(
                      margin: const EdgeInsets.only(bottom: 6),
                      child: ListTile(
                        leading: Icon(
                            paraFoto ? Icons.image : Icons.slideshow_rounded,
                            color: Colors.amberAccent),
                        title: Text(name,
                            maxLines: 1, overflow: TextOverflow.ellipsis),
                        subtitle: Text(f.parent.path,
                            style: const TextStyle(fontSize: 10)),
                        onTap: () {
                          Navigator.pop(ctx);
                          if (paraFoto) {
                            _archivosYaVistos.add(f.path);
                            _procesarNuevaFoto(f, esManual: true);
                          } else {
                            _cargarArchivoPptOPdf(f);
                          }
                        },
                      ),
                    );
                  },
                ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Cerrar'),
          ),
        ],
      ),
    );
  }

  Future<List<File>> _buscarFotosEnTelefono() async {
    final rutas = [
      '/storage/emulated/0/Pictures/SayCheese',
      '/storage/emulated/0/DCIM/SayCheese',
      '/storage/emulated/0/DCIM/Camera',
      '/storage/emulated/0/Pictures',
      '/storage/emulated/0/Download',
    ];
    final encontrados = <File>[];
    for (final r in rutas) {
      try {
        final d = Directory(r);
        if (await d.exists()) {
          for (final ent in d.listSync(recursive: false)) {
            if (ent is File) {
              final p = ent.path.toLowerCase();
              if (p.endsWith('.jpg') ||
                  p.endsWith('.jpeg') ||
                  p.endsWith('.png')) {
                encontrados.add(ent);
              }
            }
          }
        }
      } catch (_) {}
    }
    encontrados
        .sort((a, b) => b.lastModifiedSync().compareTo(a.lastModifiedSync()));
    return encontrados.take(40).toList();
  }

  // Conexion directa por enlace de Google Drive, Google Slides o Google Docs
  Future<void> _importarLinkGoogleDriveOSlides(String urlRaw) async {
    final link = urlRaw.trim();
    if (link.isEmpty) return;

    try {
      await _esperarConexionRedActiva();
      final matchId = RegExp(r'/d/([a-zA-Z0-9_-]+)').firstMatch(link) ??
          RegExp(r'id=([a-zA-Z0-9_-]+)').firstMatch(link);

      if (matchId == null) {
        throw Exception(
            'Enlace no reconocido. Asegurate de pegar un enlace de Google Drive o Google Slides.');
      }

      final docId = matchId.group(1)!;
      String textoDescargado = '';
      String nombreDoc =
          'Google_Drive_${docId.substring(0, min(5, docId.length))}.pptx';

      final exportTxtUrl = Uri.parse(
          'https://docs.google.com/presentation/d/$docId/export/txt');
      final resTxt = await http.get(exportTxtUrl);
      if (resTxt.statusCode == 200 &&
          resTxt.body.trim().isNotEmpty &&
          !resTxt.body.trimLeft().startsWith('<!DOCTYPE')) {
        textoDescargado = resTxt.body.trim();
        nombreDoc =
            'Google_Slides_${docId.substring(0, min(5, docId.length))}.pptx';
      }

      if (textoDescargado.isEmpty) {
        final exportPptxUrl = Uri.parse(
            'https://docs.google.com/presentation/d/$docId/export/pptx');
        final resPptx = await http.get(exportPptxUrl);
        if (resPptx.statusCode == 200) {
          try {
            textoDescargado = _extraerTextoDeBytesPptx(resPptx.bodyBytes);
          } catch (_) {}
        }
      }

      if (textoDescargado.isEmpty) {
        final driveDownloadUrl = Uri.parse(
            'https://drive.google.com/uc?export=download&id=$docId');
        final resDrive = await http.get(driveDownloadUrl);
        if (resDrive.statusCode == 200) {
          try {
            textoDescargado = _extraerTextoDeBytesPptx(resDrive.bodyBytes);
          } catch (_) {
            final posibleTxt =
                utf8.decode(resDrive.bodyBytes, allowMalformed: true);
            if (!posibleTxt.trimLeft().startsWith('<!DOCTYPE')) {
              textoDescargado = posibleTxt;
            }
          }
        }
      }

      if (textoDescargado.isEmpty) {
        final docTxtUrl = Uri.parse(
            'https://docs.google.com/document/d/$docId/export?format=txt');
        final resDoc = await http.get(docTxtUrl);
        if (resDoc.statusCode == 200 &&
            !resDoc.body.trimLeft().startsWith('<!DOCTYPE')) {
          textoDescargado = resDoc.body.trim();
          nombreDoc =
              'Google_Doc_${docId.substring(0, min(5, docId.length))}.txt';
        }
      }

      if (textoDescargado.trim().isEmpty) {
        throw Exception(
            'No se pudo leer el enlace (verifica que en Google Drive tenga permiso "Cualquier persona con el enlace").');
      }

      await _activarYCompartirPpt(
        nombre: nombreDoc,
        textoExtraido: textoDescargado,
        autor: _aliasUsuario,
      );

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text(
                  'Presentacion importada de Google Drive y compartida en la sala: $nombreDoc')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al importar de Drive: $e')),
        );
      }
    }
  }

  Future<void> _cargarArchivoPptOPdf(File archivo) async {
    final nombre = archivo.path.split('/').last;
    try {
      final bytes = await archivo.readAsBytes();
      final b64 = base64Encode(bytes);
      await _procesarBytesDeArchivoSubido(nombre, bytes, b64);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al leer el archivo: $e')),
        );
      }
    }
  }

  Future<void> _quitarPptCargado() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('ppt_nombre');
    await prefs.remove('ppt_autor');
    await prefs.remove('ppt_texto');
    await prefs.remove('pdf_base64');
    if (mounted) {
      setState(() {
        _nombreArchivoContexto = '';
        _autorPptActivo = '';
        _textoExtraidoPpt = '';
        _base64PdfContexto = null;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
            content: Text(
                'PPT desvinculado. Ahora Gemini respondera sin material externo.')),
      );
    }
  }

  Future<List<File>> _buscarArchivosPptEnTelefono() async {
    final rutasBusqueda = [
      '/storage/emulated/0/Download',
      '/storage/emulated/0/Documents',
      '/storage/emulated/0/Pictures/SayCheese',
      '/storage/emulated/0/DCIM/SayCheese',
      '/storage/emulated/0/Android/media/com.whatsapp/WhatsApp/Media/WhatsApp Documents',
    ];
    final List<File> encontrados = [];

    for (final ruta in rutasBusqueda) {
      try {
        final dir = Directory(ruta);
        if (await dir.exists()) {
          final entidades = dir.listSync(recursive: false);
          for (final ent in entidades) {
            if (ent is File) {
              final p = ent.path.toLowerCase();
              if (p.endsWith('.pptx') ||
                  p.endsWith('.pdf') ||
                  p.endsWith('.txt')) {
                encontrados.add(ent);
              }
            }
          }
        }
      } catch (_) {}
    }
    encontrados
        .sort((a, b) => b.lastModifiedSync().compareTo(a.lastModifiedSync()));
    return encontrados;
  }

