  String _topicoNtfyDeSala(String sala) {
    final limpio = _limpiarCodigoSala(sala).replaceAll('-', '');
    return 'sc_room_v12_$limpio';
  }

  Future<void> _publicarEventoEnSala(Map<String, dynamic> payload) async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      await _esperarConexionRedActiva();
      final topic = _topicoNtfyDeSala(_codigoSala);
      final url = Uri.parse('https://ntfy.sh/$topic');

      final rawJson = jsonEncode(payload);
      final comprimido = gzip.encode(utf8.encode(rawJson));
      final b64 = base64Encode(comprimido);

      if (b64.length <= 3000) {
        final paqueteUnico = jsonEncode({'z': b64});
        await http
            .post(url, body: paqueteUnico)
            .timeout(const Duration(seconds: 15));
      } else {
        final msgId = DateTime.now().millisecondsSinceEpoch.toString();
        const tamanoChunk = 2500;
        final totalChunks = (b64.length / tamanoChunk).ceil();
        for (int i = 0; i < totalChunks; i++) {
          final inicio = i * tamanoChunk;
          final fin = min(inicio + tamanoChunk, b64.length);
          final parte = b64.substring(inicio, fin);
          final paqueteParte = jsonEncode({
            'm': msgId,
            'i': i,
            'n': totalChunks,
            'c': parte,
          });
          await http
              .post(url, body: paqueteParte)
              .timeout(const Duration(seconds: 15));
        }
      }
    } catch (_) {}
  }

