  Future<void> _iniciarAgente() async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    for (final ruta in _rutasVigiladas) {
      final dir = Directory(ruta);
      if (ruta == _rutaCarpeta && !await dir.exists()) {
        try {
          await dir.create(recursive: true);
        } catch (_) {}
      }
      if (await dir.exists()) {
        try {
          if (_archivosYaVistos.isEmpty) {
            for (final ent in dir.listSync(recursive: false)) {
              if (ent is File) {
                _archivosYaVistos.add(ent.path);
              }
            }
          }
          final watcher = DirectoryWatcher(ruta);
          final sub = watcher.events.listen((event) {
            if (event.type == ChangeType.ADD ||
                event.type == ChangeType.MODIFY) {
              _verificarArchivoDetectado(File(event.path));
            }
          });
          _watchersSubs.add(sub);
        } catch (_) {}
      }
    }

    _pollingCarpetaTimer?.cancel();
    _pollingCarpetaTimer = Timer.periodic(
        const Duration(seconds: 3), (_) => _escanearCarpetasSayCheese());

    if (mounted) setState(() => _agenteActivo = true);
  }

  Future<void> _escanearCarpetasSayCheese() async {
    for (final ruta in _rutasVigiladas) {
      try {
        final dir = Directory(ruta);
        if (!await dir.exists()) continue;
        final entidades = dir.listSync(recursive: false);
        for (final ent in entidades) {
          if (ent is File) {
            await _verificarArchivoDetectado(ent);
          }
        }
      } catch (_) {}
    }
  }

  Future<void> _verificarArchivoDetectado(File archivo) async {
    final path = archivo.path;
    final name = path.split('/').last;
    if (name.startsWith('.')) return;
    if (_archivosYaVistos.contains(path)) return;

    final pathLower = path.toLowerCase();
    if (pathLower.endsWith('.jpg') ||
        pathLower.endsWith('.jpeg') ||
        pathLower.endsWith('.png')) {
      _archivosYaVistos.add(path);
      await _procesarNuevaFoto(archivo);
    } else if (pathLower.endsWith('.pptx') || pathLower.endsWith('.pdf')) {
      _archivosYaVistos.add(path);
      await _cargarArchivoPptOPdf(archivo);
    }
  }

  Future<void> _procesarNuevaFoto(File archivoImagen,
      {bool esManual = false}) async {
    final prefs = await SharedPreferences.getInstance();
    final modeloActual =
        prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasActual = prefs.getString('alias_usuario') ?? _aliasUsuario;

    final nuevoItem = EjercicioResuelto(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      rutaImagen: archivoImagen.path,
      fecha: DateTime.now(),
      autor: aliasActual,
      modeloUsado: modeloActual,
      nombrePptUsado:
          _nombreArchivoContexto.isNotEmpty ? _nombreArchivoContexto : null,
      procesando: true,
    );

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloActual;
        _aliasUsuario = aliasActual;
        _historial.insert(0, nuevoItem);
      });
    }

    if (!esManual) {
      await Future.delayed(const Duration(seconds: 1));
    }

    await _guardarHistorialLocal();
    await _intentarResolver(nuevoItem);
  }

  Future<void> _intentarResolver(EjercicioResuelto item) async {
    if (item.rutaImagen == null) return;

    final prefs = await SharedPreferences.getInstance();
    final modeloElegido =
        prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasElegido = prefs.getString('alias_usuario') ?? _aliasUsuario;

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloElegido;
        _aliasUsuario = aliasElegido;
        item.modeloUsado = modeloElegido;
        item.autor = aliasElegido;
        item.nombrePptUsado =
            _nombreArchivoContexto.isNotEmpty ? _nombreArchivoContexto : null;
        item.procesando = true;
        item.solucion = null;
      });
    }
    await _guardarHistorialLocal();

    try {
      final respuesta = await _llamarGeminiModoEstricto(
          File(item.rutaImagen!), modeloElegido);
      if (mounted) {
        setState(() {
          item.solucion = _limpiarRespuestaMarkdown(respuesta);
          item.modeloUsado = modeloElegido;
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
      await _publicarSolucionIndividualEnSala(item);
    } catch (e) {
      if (mounted) {
        setState(() {
          item.solucion = 'Error al resolver con $modeloElegido: $e';
          item.modeloUsado = modeloElegido;
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
    }
  }

  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  Future<void> _esperarConexionRedActiva() async {
    for (int intento = 0; intento < 6; intento++) {
      try {
        final lookup =
            await InternetAddress.lookup('generativelanguage.googleapis.com')
                .timeout(const Duration(seconds: 3));
        if (lookup.isNotEmpty && lookup.first.rawAddress.isNotEmpty) {
          return;
        }
      } catch (_) {
        await Future.delayed(const Duration(seconds: 2));
      }
    }
  }

  Future<String> _llamarGeminiModoEstricto(
      File imagen, String modeloElegido) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception('Configura tu clave en el icono de engranaje superior.');
    }

    final bytes = await imagen.readAsBytes();
    final base64Image = base64Encode(bytes);
    final modActual = modeloElegido.trim();

    String promptTexto =
        "Resuelve todos los ejercicios de esta hoja paso a paso. Usa formato Markdown claro, enumera cada ejercicio y destaca el resultado final en negrita (NUNCA uses bloques de codigo ni sangrias de 4 espacios para el resultado final).";

    if (_nombreArchivoContexto.isNotEmpty && _textoExtraidoPpt.isNotEmpty) {
      promptTexto +=
          "\n\nIMPORTANTE: Responde y resuelve los ejercicios basandote ESTRICTAMENTE en el siguiente contenido de la presentacion PowerPoint / documento ($_nombreArchivoContexto):\n\n$_textoExtraidoPpt";
    } else if (_nombreArchivoContexto.isNotEmpty &&
        _base64PdfContexto != null) {
      promptTexto +=
          "\n\nIMPORTANTE: Responde y resuelve los ejercicios de la imagen basandote ESTRICTAMENTE en el documento PDF adjunto ($_nombreArchivoContexto).";
    }

    final List<Map<String, dynamic>> parts = [
      {"text": promptTexto},
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      }
    ];

    if (_base64PdfContexto != null && _base64PdfContexto!.isNotEmpty) {
      parts.add({
        "inline_data": {
          "mime_type": "application/pdf",
          "data": _base64PdfContexto,
        }
      });
    }

    await _esperarConexionRedActiva();

    final List<Map<String, dynamic>> payloadsParaProbar = [
      if (modActual.contains('pro'))
        {
          "contents": [
            {"parts": parts}
          ],
          "generationConfig": {
            "thinkingConfig": {"thinkingBudget": 4096}
          }
        },
      {
        "contents": [
          {"parts": parts}
        ],
      },
    ];

    final List<Map<String, dynamic>> modosAutenticacion = [
      {
        'url': Uri.parse(
            'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent?key=$keyLimpia'),
        'headers': {'Content-Type': 'application/json'},
      },
      {
        'url': Uri.parse(
            'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent'),
        'headers': {
          'Content-Type': 'application/json',
          'x-goog-api-key': keyLimpia,
        },
      },
      {
        'url': Uri.parse(
            'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent'),
        'headers': {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer $keyLimpia',
        },
      },
    ];

    http.Response? response;
    Object? ultimoErrorRed;

    for (int intento = 0; intento < 3; intento++) {
      try {
        for (final payloadActual in payloadsParaProbar) {
          for (int m = 0; m < modosAutenticacion.length; m++) {
            final modo = modosAutenticacion[m];
            final res = await http
                .post(
                  modo['url'] as Uri,
                  headers: Map<String, String>.from(modo['headers'] as Map),
                  body: jsonEncode(payloadActual),
                )
                .timeout(const Duration(seconds: 120));

            response = res;

            if (res.statusCode == 200 ||
                res.statusCode == 429 ||
                res.statusCode == 404) {
              break;
            }
          }
          if (response != null &&
              (response.statusCode == 200 || response.statusCode == 429)) {
            break;
          }
        }

        if (response != null && response.statusCode == 429 && intento < 1) {
          await Future.delayed(const Duration(seconds: 5));
          continue;
        }
        break;
      } catch (e) {
        ultimoErrorRed = e;
        await Future.delayed(const Duration(seconds: 3));
        await _esperarConexionRedActiva();
      }
    }

    if (response == null) {
      throw Exception(
          'Sin respuesta de red tras varios intentos (verifica tu conexion Wi-Fi / 4G): $ultimoErrorRed');
    }

    if (response.statusCode == 200) {
      final data = jsonDecode(response.body);
      final respParts = data['candidates'][0]['content']['parts'] as List;
      final textPart = respParts.lastWhere(
        (p) => p.containsKey('text') && p['thought'] != true,
        orElse: () => respParts.last,
      );
      return textPart['text'].toString();
    } else if (response.statusCode == 429) {
      throw Exception(
          'Limite de cuota gratuita (429) en Google AI Studio para el modelo "$modActual": ${response.body}');
    } else {
      throw Exception(
          'Codigo ${response.statusCode} en $modActual: ${response.body}');
    }
  }

  Future<List<String>> _descubrirModelosActivosEnCuenta(String apiKey) async {
    try {
      await _esperarConexionRedActiva();
      final url = Uri.parse(
          'https://generativelanguage.googleapis.com/v1beta/models?key=$apiKey');
      var res = await http.get(url);
      if (res.statusCode != 200) {
        res = await http.get(
          Uri.parse('https://generativelanguage.googleapis.com/v1beta/models'),
          headers: {'Authorization': 'Bearer $apiKey'},
        );
      }
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body);
        final models = data['models'] as List? ?? [];
        final disponibles = <String>[];
        for (final m in models) {
          final name = (m['name'] as String? ?? '').replaceFirst('models/', '');
          final methods = (m['supportedGenerationMethods'] as List? ?? [])
              .map((e) => e.toString())
              .toList();
          if (methods.contains('generateContent') &&
              name.startsWith('gemini') &&
              !name.contains('embedding') &&
              !name.contains('imagen') &&
              !name.contains('tts')) {
            disponibles.add(name);
          }
        }
        return disponibles;
      }
    } catch (_) {}
    return [];
  }

