                              Text('Resolviendo con ${item.modeloUsado}...'),
                          subtitle: const LinearProgressIndicator(),
                          trailing: IconButton(
                            icon: const Icon(Icons.delete_outline,
                                color: Colors.redAccent),
                            onPressed: () => _eliminarSolucion(item),
                          ),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildVistaSoluciones(List<EjercicioResuelto> resueltos) {
    return Column(
      children: [
        if (_codigoSala.isNotEmpty)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
            color: Colors.deepPurple.withOpacity(0.25),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Sala: $_codigoSala • Canal: ${_topicoNtfyDeSala(_codigoSala)}',
                        style: const TextStyle(
                            fontSize: 12, fontWeight: FontWeight.bold),
                        overflow: TextOverflow.ellipsis,
                      ),
                      if (_nombreArchivoContexto.isNotEmpty)
                        Text(
                          'PPT de la sala: $_nombreArchivoContexto (por ${_autorPptActivo.isNotEmpty ? _autorPptActivo : "Compañero"})',
                          style: const TextStyle(
                              fontSize: 11, color: Colors.amberAccent),
                          overflow: TextOverflow.ellipsis,
                        ),
                    ],
                  ),
                ),
                TextButton.icon(
                  icon: _sincronizando
                      ? const SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(strokeWidth: 2))
                      : const Icon(Icons.sync, size: 16),
                  label: const Text('Sincronizar',
                      style: TextStyle(fontSize: 12)),
                  onPressed: () => _sincronizarSalaCompartida(),
                ),
                TextButton.icon(
                  style:
                      TextButton.styleFrom(foregroundColor: Colors.redAccent),
                  icon: const Icon(Icons.logout, size: 16),
                  label: const Text('Salir', style: TextStyle(fontSize: 12)),
                  onPressed: _abandonarSala,
                ),
              ],
            ),
          ),
        Expanded(
          child: resueltos.isEmpty
              ? const Center(
                  child: Text('Aun no hay hojas resueltas en este apartado.'),
                )
              : ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: resueltos.length,
                  itemBuilder: (context, index) {
                    final item = resueltos[index];
                    final tieneFotoLocal = item.rutaImagen != null &&
                        File(item.rutaImagen!).existsSync();
                    return Dismissible(
                      key: Key('sol_${item.id}'),
                      direction: DismissDirection.endToStart,
                      background: Container(
                        alignment: Alignment.centerRight,
                        padding: const EdgeInsets.symmetric(horizontal: 20),
                        margin: const EdgeInsets.only(bottom: 12),
                        decoration: BoxDecoration(
                          color: Colors.redAccent,
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: const Icon(Icons.delete, color: Colors.white),
                      ),
                      onDismissed: (_) => _eliminarSolucion(item),
                      child: Card(
                        margin: const EdgeInsets.only(bottom: 12),
                        child: ListTile(
                          contentPadding: const EdgeInsets.all(12),
                          leading: ClipRRect(
                            borderRadius: BorderRadius.circular(8),
                            child: tieneFotoLocal
                                ? Image.file(
                                    File(item.rutaImagen!),
                                    width: 60,
                                    height: 60,
                                    fit: BoxFit.cover,
                                    errorBuilder: (_, __, ___) =>
                                        const Icon(Icons.image, size: 40),
                                  )
                                : Container(
                                    width: 60,
                                    height: 60,
                                    color: Colors.deepPurple.withOpacity(0.3),
                                    child:
                                        const Icon(Icons.cloud_done, size: 32),
                                  ),
                          ),
                          title: Text(
                              'Hoja #${resueltos.length - index} • ${item.autor}'),
                          subtitle: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                item.nombrePptUsado != null
                                    ? 'Modelo: ${item.modeloUsado} • PPT: ${item.nombrePptUsado}'
                                    : 'Modelo: ${item.modeloUsado}',
                                style: const TextStyle(
                                    fontSize: 11,
                                    color: Colors.deepPurpleAccent),
                              ),
                              const SizedBox(height: 4),
                              Text(
                                item.solucion ?? '',
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                              ),
                            ],
                          ),
                          trailing: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              if (tieneFotoLocal)
                                IconButton(
                                  icon: const Icon(Icons.refresh),
                                  tooltip:
                                      'Reintentar con $_modeloSeleccionado',
                                  onPressed: () => _intentarResolver(item),
                                ),
                              IconButton(
                                icon: const Icon(Icons.delete_outline,
                                    color: Colors.redAccent),
                                tooltip: 'Eliminar esta solucion',
                                onPressed: () => _eliminarSolucion(item),
                              ),
                            ],
                          ),
                          onTap: () async {
                            await Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder: (_) => DetalleSolucionScreen(
                                  ejercicio: item,
                                  onReintentar: tieneFotoLocal
                                      ? () {
                                          Navigator.pop(context);
                                          _intentarResolver(item);
                                        }
                                      : null,
                                  onEliminar: () {
                                    Navigator.pop(context);
                                    _eliminarSolucion(item);
                                  },
                                ),
                              ),
                            );
                          },
                        ),
                      ),
                    );
                  },
                ),
        ),
      ],
    );
  }
}

class DetalleSolucionScreen extends StatelessWidget {
  final EjercicioResuelto ejercicio;
  final VoidCallback? onReintentar;
  final VoidCallback? onEliminar;

  const DetalleSolucionScreen({
    super.key,
    required this.ejercicio,
    this.onReintentar,
    this.onEliminar,
  });

  @override
  Widget build(BuildContext context) {
    final tieneFotoLocal = ejercicio.rutaImagen != null &&
        File(ejercicio.rutaImagen!).existsSync();

    final markdownDarkSheet =
        MarkdownStyleSheet.fromTheme(Theme.of(context)).copyWith(
      p: const TextStyle(color: Colors.white, fontSize: 15, height: 1.45),
      h1: const TextStyle(
          color: Colors.white, fontSize: 20, fontWeight: FontWeight.bold),
      h2: const TextStyle(
          color: Colors.white, fontSize: 18, fontWeight: FontWeight.bold),
      h3: const TextStyle(
          color: Colors.deepPurpleAccent,
          fontSize: 16,
          fontWeight: FontWeight.bold),
      strong: const TextStyle(
          color: Colors.amberAccent, fontWeight: FontWeight.bold),
      blockquote: const TextStyle(color: Colors.white, fontSize: 15),
      blockquoteDecoration: BoxDecoration(
        color: const Color(0xFF252336),
        borderRadius: BorderRadius.circular(8),
        border: const Border(
          left: BorderSide(color: Colors.deepPurpleAccent, width: 4),
        ),
      ),
      code: const TextStyle(
        color: Colors.white,
        backgroundColor: Color(0xFF252336),
        fontFamily: 'monospace',
        fontSize: 14,
      ),
      codeblockPadding: const EdgeInsets.all(14),
      codeblockDecoration: BoxDecoration(
        color: const Color(0xFF252336),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
            color: Colors.deepPurpleAccent.withOpacity(0.5), width: 1),
      ),
    );

    return Scaffold(
      appBar: AppBar(
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Solucion (${ejercicio.autor})',
                style: const TextStyle(fontSize: 17)),
            Text(
              ejercicio.nombrePptUsado != null
                  ? 'Resuelto con: ${ejercicio.modeloUsado} (PPT: ${ejercicio.nombrePptUsado})'
                  : 'Resuelto con: ${ejercicio.modeloUsado}',
              style:
                  const TextStyle(fontSize: 11, color: Colors.greenAccent),
            ),
          ],
        ),
        actions: [
          if (onReintentar != null)
            IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: 'Reintentar',
              onPressed: onReintentar,
            ),
          if (onEliminar != null)
            IconButton(
              icon: const Icon(Icons.delete_outline, color: Colors.redAccent),
              tooltip: 'Eliminar esta solucion',
              onPressed: onEliminar,
            ),
        ],
      ),
      body: Column(
        children: [
          if (tieneFotoLocal)
            SizedBox(
              height: 180,
              width: double.infinity,
              child: InteractiveViewer(
                child: Image.file(
                  File(ejercicio.rutaImagen!),
                  fit: BoxFit.contain,
                  errorBuilder: (_, __, ___) =>
                      const Center(child: Icon(Icons.broken_image, size: 48)),
                ),
              ),
            ),
          const Divider(height: 1),
          Expanded(
            child: Markdown(
              data: ejercicio.solucion ?? 'Sin respuesta.',
              selectable: true,
              styleSheet: markdownDarkSheet,
            ),
          ),
        ],
      ),
    );
  }
}
